/* Override checkbox and radio button styles because they inherit their look from the OS which makes them ugly and
unresponsive to our theme. */
/*-------------------------------------------------------------
    Checkbox
-------------------------------------------------------------*/
input[type=checkbox] {
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;
    color: var(--gw-checkbox-color);
    background-color: var(--gw-checkbox-background);
    border: 1px solid var(--gw-checkbox-border-color);
    width: 1em;
    height: 1em;
    display: inline-block;
    vertical-align: middle;
    cursor: pointer;
}

input[type=checkbox]:hover {
    border-color: var(--gw-checkbox-hover-border-color);
}

input[type=checkbox]:hover:checked {
    background-color: var(--gw-checkbox-checked-hover-background);
    border-color: var(--gw-checkbox-checked-hover-border-color);
}

input[type=checkbox]:checked {
    background-color: var(--gw-checkbox-checked-background);
    border-color: var(--gw-checkbox-checked-border-color);
}

input[type=checkbox]:checked:disabled {
    background-color: var(--gw-checkbox-checked-disabled-background);
    border-color: var(--gw-checkbox-checked-disabled-border-color);
    opacity: var(--gw-checkbox-disabled-opacity);
}

input[type=checkbox]:disabled {
    background-color: var(--gw-checkbox-disabled-background);
    opacity: var(--gw-checkbox-disabled-opacity);
}

input[type=checkbox]:checked::after {
    content: "\\2713"; /* checkmark */
    display: block;
    text-align: center;
    color: var(--gw-checkbox-icon-checked-color);
    font-size: 0.8em;
    line-height: 1.2;
}

input[type=checkbox]:checked:hover::after {
    color: var(--gw-checkbox-icon-checked-hover-color);
}

input[type=checkbox]:checked:disabled::after {
    color: var(--gw-checkbox-icon-disabled-color);
}

/*-------------------------------------------------------------
    Radio button
-------------------------------------------------------------*/

input[type=radio] {
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;
    color: var(--gw-radiobutton-label-color);
    background-color: var(--gw-radiobutton-background);
    border: 1px solid var(--gw-radiobutton-border-color);
    width: 1em;
    height: 1em;
    display: inline-block;
