/*-------------------------------------------------------------
	Switch control
-------------------------------------------------------------*/


span.switch {
    clear: both;
    margin: 0 5px;
    width: 36px;
}

input.switch:empty {
    display: none
}

input.switch:empty ~ label {
    position: relative;
    cursor: pointer;
    -webkit-user-select: none;
    -moz-user-select: none;
    -ms-user-select: none;
    user-select: none;
    margin: 0.05em 0.6em -0.05em 0;
    vertical-align: text-bottom;
}

input.switch:empty ~ label:before {
    display: block;
    content: ' ';
    width: 2.2em;
    height: 1.25em;
    background-color: var(--gw-toggleswitch-background);
    border-radius: 10em;
    -moz-transition: all 100ms ease-in; /* FF4+ */
    -o-transition: all 100ms ease-in; /* Opera 10.5+ */
    -webkit-transition: all 100ms ease-in; /* Saf3.2+, Chrome */
    transition: all 100ms ease-in;
}

input.switch:empty ~ label:after {
    position: absolute;
    display: block;
    top: 0.1em;
    left: 0.1em;
    content: ' ';
    width: 1.05em;
    height: 1.05em;
    background-color: var(--gw-toggleswitch-handle-background);
    border-radius: 50%;
    -moz-transition: all 100ms ease-in; /* FF4+ */
    -o-transition: all 100ms ease-in; /* Opera 10.5+ */
    -webkit-transition: all 100ms ease-in; /* Saf3.2+, Chrome */
    transition: all 100ms ease-in;
}

input.switch:empty ~ label:hover:after {
    background-color: var(--gw-toggleswitch-handle-hover-background);
}

input.switch:checked ~ label:before {
    background-color: var(--gw-toggleswitch-checked-background);
}

input.switch:checked ~ label:hover:before {
    background-color: var(--gw-toggleswitch-checked-hover-background);
}

input.switch:checked:disabled ~ label:hover:before {
    background-color: var(--gw-toggleswitch-disabled-background);
}

input.switch:checked ~ label:after {
    left: 1.05em;
    background-color: var(--gw-toggleswitch-handle-checked-background);
}

input.switch:checked ~ label:hover:after {
    background-color: var(--gw-toggleswitch-handle-checked-hover-background);
}

input.switch:disabled ~ label:before {
    background-color: var(--gw-toggleswitch-disabled-background);
}

input.switch:disabled ~ label:before, input.switch:disabled ~ label:after {
    cursor: not-allowed;
}

.card.active input.switch:checked ~ label:before {
    background-color: rgba(255, 255, 255, .5);
}

.card.active input.switch:checked ~ label:after {
    background-color: #fff;
}

