    -moz-transition: max-height 0.5s ease-in; /* FF4+ */
    -o-transition: max-height 0.5s ease-in; /* Opera 10.5+ */
    -webkit-transition: max-height 0.5s ease-in; /* Saf3.2+, Chrome */
    transition: max-height 0.5s ease-in;
}

/*-------------------------------------------------------------
    Graphs visualizations side panel
-------------------------------------------------------------*/

.rdf-side-panel-content .tab-content {
    overflow-y: auto;
    width: 100%;
    max-height: calc(100vh - 130px);
}

.menu-events g {
    cursor: pointer;
    opacity: 0;
}

.tags .tag-list li.tag-item {
    height: auto !important;
    white-space: normal !important;
}


/*-------------------------------------------------------------
    Badges
-------------------------------------------------------------*/
.badge {
    display: inline-block;
    padding: .25em .4em;
    font-size: 75%;
    font-weight: 400;
    line-height: 1;
    color: #fff;
    text-align: center;
    white-space: nowrap;
    vertical-align: baseline;
    border-radius: .25rem;
}
.badge-default  { background-color: #aaa }
.badge-primary  { background-color: var(--gw-secondary-base) }
.badge-info     { background-color: var(--gw-primary-base) }
.badge-success  { background-color: #5cb85c }
.badge-warning  { background-color: #f0ad4e }

/*-------------------------------------------------------------
    Columns
-------------------------------------------------------------*/
@media (min-width: 992px) {
    .col-lg-no-padding {
        padding-left: 0 !important;
        padding-right: 0 !important;
    }
}

/*-------------------------------------------------------------
    Custom tags-input styling, overrides some
    of the styles from ng-tags-input.min.css
-------------------------------------------------------------*/
tags-input[disabled] .tags {
    color: var(--gw-form-field-disabled-color);
    background-color: var(--gw-form-field-disabled-background) !important;
}

tags-input[disabled] .tags .input {
    color: var(--gw-form-field-disabled-color);
    background-color: var(--gw-form-field-disabled-background) !important;
}

tags-input .tags .input {
    color: var(--gw-form-field-color);
    background-color: var(--gw-form-field-background);
}

.wb-tags-input .tags {
    background-color: var(--gw-form-field-background);
    border: 1px solid var(--gw-form-field-border-color);
    border-radius: 0;
    box-shadow: inset 0 1px 1px rgba(0,0,0,0.075);
    transition: border-color ease-in-out .15s, box-shadow ease-in-out .15s;
}

.wb-tags-input .tags.focused {
    outline: 0;
    -webkit-box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.075), 0 0 6px #cbeeea;
    -moz-box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.075), 0 0 6px #cbeeea;
    box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.075), 0 0 6px #cbeeea;
}

.wb-tags-input .tags .tag-item {
    background: #cbeeea;
    border: 1px solid #cbeeea;
    border-radius: 0;
    color: #3D3D3D;
}

.wb-tags-input .tags .tag-item.tag-item-wildcard {
    background: #cbeeea;
    border: 1px solid #cbeeea;
    border-radius: 0;
    color: #3D3D3D;
    font-weight: bold;
}

.wb-tags-input .tags .tag-item .remove-button {
    margin: 0 0 0 5px;
    padding: 0;
    border: none;
    background: 0 0;
    cursor: pointer;
    vertical-align: middle;
    font: 700 16px Arial,sans-serif;
    color: #7e7b6d;
}

/*-------------------------------------------------------------
	Main menu
-------------------------------------------------------------*/
.repo-info-home {
    display: flex;
    flex-direction: row;
    align-items: flex-start;
}

.repo-info-home div {
    align-self: center;
}

.tag-default {
    color: var(--gw-tag-default-color) !important;
    background-color: var(--gw-tag-default-background) !important;
}

.tag-danger {
    color: var(--gw-tag-danger-color) !important;
    background-color: var(--gw-tag-danger-background) !important;
}

.tag-success {
    color: var(--gw-tag-success-color) !important;
    background-color: var(--gw-tag-success-background) !important;
}

.tag-warning {
    color: var(--gw-tag-warning-color) !important;
    background-color: var(--gw-tag-warning-background) !important;
}

.tag-info {
    color: var(--gw-tag-info-color) !important;
    background-color: var(--gw-tag-info-background) !important;
}

.rzslider .rz-pointer {
    background-color: var(--gw-slider-handle-focus-ring-color) !important;
    outline: none !important;
}

.rzslider .rz-pointer:hover {
    background-color: var(--gw-slider-handle-hover-background) !important;
}

.rzslider .rz-pointer:after {
    background-color: var(--gw-slider-track-background) !important;
}

.rzslider .rz-pointer.rz-active:after {
    background-color: var(--gw-slider-range-background) !important;
}

.rzslider .rz-bar {
    background-color: var(--gw-slider-track-background) !important;
}

.rzslider .rz-selection {
    background: var(--gw-slider-range-background) !important;
}

.rzslider .rz-bubble.rz-limit,
.rzslider .rz-bubble {
    color: var(--gw-slider-label-color) !important;
}

.login-form {
    max-width: 600px;
    padding-top: 4em;
    margin: auto;
}

.btn-fade-warning {
    animation: fade-button 2s infinite;
    --fade-color: var(--gw-warning-lighter);
}

.btn-fade-danger {
    animation: fade-button 2s infinite;
    --fade-color: var(--gw-error-lighter);
}

.btn-fade-warning:hover, .btn-fade-danger:hover {
    background-color: var(--fade-color) !important;
    border-color: var(--fade-color) !important;
}

@keyframes fade-button {
    from {
        background-color: transparent;
        border-color: transparent;
    }
    50% {
        background-color: var(--fade-color);
        border-color: var(--fade-color);
    }
    to {
        background-color: transparent;
        border-color: transparent;
    }
}

.ot-loader-new-content circle {
    fill: var(--gw-loader-color)
}
